/// <summary>
/// Superclass for formatting the xml. All Format classes extends this class.
/// </summary>
class TFMXMLFormat
{
    Common              common;
    XmlDocument         resultXml;
    TFMOrderTypes       orderType;
    TFMPageID			pageName;
    str                 imageID;
    str                 sorting;
    str                 displayLine1;
    str                 displayLine2;
    str                 displayLine3;
    str                 displayLine4;
    str                 displayLine5;
    Map                 fieldsToAdd;
    Map					fieldsFromDS;
    Map					MenuItemsConf;
    SysDictTable		sdt;
    TFMPage				page;
    TFMPageDatasources	ds;
    str					recordLineTag;
    Map                 cachedResponse;
    TFMDocumentDeviceId deviceId;
}

Method.Source:
public TFMDocumentDeviceId parmDeviceId(TFMDocumentDeviceId _deviceId = deviceId)
{
    deviceId = _deviceId;
    return deviceId;
}

	public TFMPageDatasources dataSource()
    {
        return ds;
    }

	public Map parmFieldsToAddMap(Map _fieldsToAdd = fieldsToAdd)
    {
        fieldsToAdd = _fieldsToAdd;
        return fieldsToAdd;
    }

	public void addFieldToOutput(str _key, str _value)
    {
        fieldsToAdd.insert(_key,_value);
    }

	public TFMPage getPage()
    {
        if (!page)
        {
            page = TFMPagesProvider::getAllPages().getPage(pageName);
        }

        return page;
    }

    public void addMenuItemsConfigurationIfExists(str _menuItemName, int _promoted, boolean _enabled)
    {
        if (MenuItemsConf.exists(_menuItemName))
        {
			this.addMenuItemsConfiguration(_menuItemName,_promoted,_enabled);
        }
    }

	public void addMenuItemsConfiguration(str _menuItemName, int _promoted, boolean _enabled)
    {
        TFMMenuItemStateConfiguration MenuItemConf = TFMMenuItemStateConfiguration::Construct(_menuItemName);
        MenuItemConf.parmEnabled(_enabled);
        MenuItemConf.parmPromoted(_promoted);
        MenuItemsConf.add(_menuItemName,MenuItemConf);
    }

	public void appendMenuItemConfigurationToXML(XmlElement _lineElement)
    {
        XmlElement						menuItemStateConfigurationsNode = _lineElement.ownerDocument().createElement(TFMConstants::menuItemStateConfigurations());
        MapEnumerator					sEnum							= MenuItemsConf.getEnumerator();
        TFMMenuItemStateConfiguration	menuItemConf;

        if (!MenuItemsConf.elements())
        {
            return;
        }

		while (sEnum.moveNext())
        {
            menuItemConf = sEnum.currentValue();
            if (menuItemConf.parmMenuItemName() == 'attachments')
            {
                menuItemConf.parmEnabled(TFMHelper::DocuRefexist(common.dataAreaId, common.tableID, common.RecId));
            } else if (MenuItemConf.parmMenuItemName() == TFMConstants::MenuItemRegisterImage() && !TFMTablesProvider::instance().isTableAllowed(common.tableId))
            {
                menuItemConf.parmEnabled(false);
            } else if (MenuItemConf.parmMenuItemName() == 'unlockOrder' && fieldsToAdd.exists(TFMConstants::Status()) && fieldsToAdd.lookup(TFMConstants::Status()) == TFMConstants::unlocked())
            {
                menuItemConf.parmEnabled(false);
            }
            menuItemConf.appendToXML(menuItemStateConfigurationsNode);
        }

        _lineElement.appendChild(menuItemStateConfigurationsNode);
    }

	public void addField(str _key, str _value)
    {
        fieldsToAdd.insert(_key,_value);
    }

public str parmDisplayLine1(str _dispLine1 = displayLine1)
{
    displayLine1 = _dispLine1;
    return displayLine1;
}

public str parmDisplayLine2(str _dispLine = displayLine2)
