    /// <summary>
    /// The initFromCommon method initializes the TFMXMLFormat class, and all of its derivatives, with standard variables needed for the classes to work.
    /// </summary>
    /// <param name = "_resultXml">The XML Document in which to add the content of the class.</param>
    /// <param name = "_common">The table buffer the class will take its data from for the XML.</param>
    /// <param name = "_sorting">The sorting of the record in the result. This field will be deprecated in future versions.</param>
    /// <param name = "_orderType">The Order Type, Optional. Used to differentiate two classes using the same buffer types but in different contexts.</param>
    public void initFromCommon(XmlDocument _resultXml, Common _common, int _sorting, TFMOrderTypes _orderType = '', TFMPageID _pageId = '')
    {
        Container            fields = TFMXMLFormat::fieldsFromCommon(_common).pack();
        fieldsToAdd		= new Map(Types::String, Types::String);
        Common          = _common;
        resultXml       = _resultXml;
        sorting         = int2str(_sorting);
        orderType       = _orderType;
        displayLine1    = conLen(fields) > 3 ? conPeek(fields,4) : '';
        fieldsToAdd.insert('DisplayLine1_Label', conLen(fields) > 4 ? conPeek(fields,5) : '');
        displayLine2    = conLen(fields) > 5 ? conPeek(fields,6) : '';
        displayLine3    = conLen(fields) > 7 ? conPeek(fields,7) : '';
        displayLine4    = conLen(fields) > 9 ? conPeek(fields,8) : '';
        displayLine5    = conLen(fields) > 11 ? conPeek(fields,10) : '';
        imageID         = fieldName2Id(_common.TableId, 'ItemId') ? _common.(fieldName2Id(_common.TableId, 'ItemId')) : '';
        pageName		= _pageId;
        MenuItemsConf   = new Map(Types::String, Types::Class);
        ds = TFMPageDatasources::FindOrCreate(_pageId,tableId2Name(_common.tableId),_orderType);
        sdt = new SysDictTable(common.tableId);

	}

public void initFromDataSource(TFMPageDatasources _ds)
{
    orderType       = _ds.OrderType;
    pageName		= _ds.PageID;
    MenuItemsConf   = new Map(Types::String, Types::Class);
    ds = _ds;
    fieldsToAdd = new Map(Types::String, Types::String);
}

	public Common parmCommon(Common _common = common)
    {
        common = _common;
        sdt = new SysDictTable(common.tableId);
        return common;
    }

public TFMPageId parmPageID(TFMPageID _pageId = pageName)
{
    pageName = _pageId;
    return pageName;
}

public static List fieldsFromCommon(Common _common)
{
    MapEnumerator   keyFields = TFMHelper::getPrimaryKeysFromTableName(tableId2Name(_common.TableID)).getEnumerator();
    DictField       dictField;
    List			ret = new List(Types::String);    
    SysDictField	sdf = new DictTable(_common.TableID).titleField1() ? new SysDictField(_common.TableID, new DictTable(_common.TableID).titleField1()) : null;

    if (sdf)
    {
        ret.addEnd(sdf.label());
        ret.addEnd(strFmt('%1',_common.(sdf.id())));
    }

    sdf = new DictTable(_common.TableID).titleField2() ? new SysDictField(_common.TableID, new DictTable(_common.TableID).titleField2()) : null;
    if (sdf)
    {
        ret.addEnd(sdf.label());
        ret.addEnd(strFmt('%1',_common.(sdf.id())));
    }

    while (keyFields.moveNext())
    {
        dictField = keyFields.currentValue();
        ret.addEnd(dictField.label());
        ret.addEnd(strFmt('%1',_common.(dictField.id())));
    }

    return ret;
}

    /// <summary>
    /// Main run method of the format classes.
    /// </summary>
    public void run()
    {
        if (!TFMOutputCacheSetup::isCacheActive(classIdGet(this),orderType) || !TFMXMLTable::exists(common,orderType) || !this.setCachedXML())
        {
            this.getPage();
            this.initDefaultMenuItemConfiguration();
            //Get Data Source fields
			this.updateDatasource();
			//Get Class Fields
			this.setValues();    
            this.enrichDataSetFromCustomComponents();
            this.convertFieldsToMap();
			//Merge DS and class fields Cls fields takes precedence
            fieldsToAdd = TFMHelper::mergeMaps(fieldsToAdd,fieldsFromDS);

			//Display Override /Delta fields
            fieldsToAdd = TFMDisplayLineOverride::FindAndExecuteFromDS(ds,Common,fieldsToAdd);
            if (page)
            {
                fieldsToAdd.insert(extendedTypeStr(TFMPageID), page.parmId());
            }
			if (resultXml != null)
            {
				//Legacy, append to xml object
                this.setXML();
            }
        }
    }

protected void enrichDataSetFromCustomComponents()
{
    SetEnumerator			sEnum;
    TFMListCustomComponent	customComponent;
    if (page == null)
    {
        return;
    }
    TFMList list = TFMListsProvider::getAllLists().getList(page.getListId());
    if(list)
    {
        sEnum = list.getListConfiguration().getCustomComponents().getEnumerator();
        while (sEnum.moveNext())
        {
            customComponent = sEnum.current();
            fieldsToAdd = customComponent.enrichDataset(common, fieldsToAdd);
        }
    }
}

	public void convertFieldsToMap()
    {
        //RefID ✔️
        fieldsToAdd.insert(tableStr(ReferenceIdentity), fieldsToAdd.exists(tableStr(ReferenceIdentity)) ? fieldsToAdd.lookup(tableStr(ReferenceIdentity)) : tableId2Name(common.TableId ) + ';' + int642Str(common.RecId ));
        fieldsToAdd.insert(TFMConstants::Attachment(),TFMHelper::DocuRefexist(common.dataAreaId, common.tableID, common.RecId) ? '1' : '0');
        fieldsToAdd.insert('attachmentImage',fieldsToAdd.lookup(TFMConstants::Attachment()) == '1' ? resourceStr(TFMAttachmentIcon) : 'unlocked');
        //DisplayLines
        this.addDisplayLine(TFMConstants::DisplayLine1(),displayLine1);
        this.addDisplayLine(TFMConstants::DisplayLine2(),displayLine2);
        this.addDisplayLine(TFMConstants::DisplayLine3(),displayLine3);
        this.addDisplayLine(TFMConstants::DisplayLine4(),displayLine4);
        this.addDisplayLine(TFMConstants::DisplayLine5(),displayLine5);
        //Sorting
        if (sorting)
        {
            fieldsToAdd.insert(TFMConstants::Sorting(), fieldsToAdd.exists(TFMConstants::Sorting()) ? fieldsToAdd.lookup(TFMConstants::Sorting()) : sorting);
        }

    }

	protected void addDisplayLine(str _key, str _value)
    {
        int breakPos= strScan(_value,': ',1,100);
        if (breakPos && !fieldsToAdd.exists(_key))
        {
			//Old style displayLine
            fieldsToAdd.insert(_key+ '_Label', subStr(_value,1,breakPos-1));
            fieldsToAdd.insert(_key, subStr(_value,breakPos+2,1000));
        }
		else
        {
			fieldsToAdd.insert(_key, fieldsToAdd.exists(_key) ? fieldsToAdd.lookup(_key) : _value);
        }
    }

	protected void initDefaultMenuItemConfiguration()
    {
        MenuItemsConf =  TFMPageMenuItemsFormHelper::getPageMenuItemStateConfigurations(pageName);        
    }

	protected void updateDatasource()
    {
        SetEnumerator		sEnum;
        TFMDataSourceBlock	dsBlock;
        fieldsFromDS = new Map(Types::String, Types::String);
		if (!pageName)
        {
            return;
        }
        ds = TFMPageDatasources::FindOrCreate(pageName,tableId2Name(common.tableId),orderType);
        sEnum = ds.GetDataSourceBlocks(common).getEnumerator();
		while (sEnum.moveNext())
        {
            dsBlock = sEnum.current();
            dsBlock.parmDeviceId(deviceId);
            fieldsFromDS = TFMHelper::mergeMaps(dsBlock.AddFields(common), fieldsFromDS);
            fieldsFromDS = TFMHelper::mergeMaps(dsBlock.getOverrideFieldsMap(), fieldsFromDS);
        }
        fieldsToAdd = TFMHelper::mergeMaps(fieldsFromDS, fieldsToAdd);
    }

	public void clearValues()
    {
        fieldsToAdd = new Map(Types::String, Types::String);
        imageID = '';
    }

    protected void setValues()
    {        
        //fieldsToAdd = new Map(Types::String, Types::String);
		if (sdt.fieldName2Id(extendedTypeStr(ItemId)))// && sdt.fieldName2Id(extendedTypeStr(InventDimId)))
        {
			//Generic image initialization based on if the record has an item id and inventDim
            imageId = TFMHelper::imageIDFromDocuref(TFMHelper::FindItemDocuref(common.(sdt.fieldName2Id(extendedTypeStr(ItemId))),sdt.fieldName2Id(extendedTypeStr(InventDimId)) ? common.(sdt.fieldName2Id(extendedTypeStr(InventDimId))) : ''));
        }
    }

	protected boolean setCachedXML()
    {
        return false;
    }

public void new()
{
    fieldsToAdd = new Map(Types::String, Types::String);
    cachedResponse = new Map(Types::String, Types::String);
}

protected void setXML()
{
}

	public void appendToXML(XmlElement _parentNode)
    {
        XmlElement recordLine = _parentNode.ownerDocument().createElement(recordLineTag);
        str         recKey      = tableId2Name(common.TableId)+int642Str(Common.RecId);
        if (cachedResponse.exists(recKey))
        {
            recordLine.innerXml(cachedResponse.lookup(recKey));
        }
        else
        {
            this.addToLineElement( recordLine );
        }
        _parentNode.appendChild(recordLine);

        if (TFMOutputCacheSetup::isCacheActive(classIdGet(this),orderType) && !TFMXMLTable::exists(common,orderType))
        {
            TFMXMLTable::StoreXML(recordLine.innerxml(),common,orderType);
        }
    }

protected void addToLineElement(XmlElement _parentNode)
{
    MapEnumerator mEnum;
    XmlElement lineElement;

    //create each field element
    mEnum = fieldsToAdd.getEnumerator();
    while (mEnum.moveNext())
    {
        lineElement = _parentNode.ownerDocument().createElement( mEnum.currentKey());
        lineElement.text( mEnum.currentValue() );
        _parentNode.appendChild( lineElement );
    }
    this.appendMenuItemConfigurationToXML(_parentNode);


}

public static TFMXMLFormat constructFromCommon(XmlDocument _resultXml, Common _common, int _sorting, TFMOrderTypes _orderType = '', ClassName _baseClassName = classStr(TFMXMLFormat))
{
    TFMXMLFormat            ret;
    TFMTableNameAttribute   tableNameAttribute = new TFMTableNameAttribute(tableId2Name(_common.TableId),_orderType);

    if (!tableNameAttribute)
    {
        tableNameAttribute = new TFMTableNameAttribute(tableId2Name(_common.TableId));
    }

    ret = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);

    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        ret = TFMGetRegistrationConfiguration::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }

    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        tableNameAttribute = new TFMTableNameAttribute(tableId2Name(_common.TableId));
        ret = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }

    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        ret = TFMGetRegistrationConfiguration::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }
    ret.initFromCommon(_resultXml, _common, _sorting, _orderType);

    return ret;
}

public static TFMXMLFormat constructFromDataSource(TFMPageDatasources _ds, ClassName _baseClassName = classStr(TFMXMLFormat))
{        
    TFMTableNameAttribute   tableNameAttribute  = new TFMTableNameAttribute(_ds.TableName,_ds.OrderType);
    TFMXMLFormat            ret                 = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);


    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        ret = TFMGetRegistrationConfiguration::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }

    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        tableNameAttribute = new TFMTableNameAttribute(_ds.TableName);
        ret = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }

    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        ret = TFMGetRegistrationConfiguration::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }
    ret.initFromDataSource(_ds);
    return ret;
}

public static TFMXMLFormat constructFromBackendID(str _backendID, ClassName _baseClassName = classStr(TFMXMLFormat))
{
    TFMXMLFormat            ret;  
    TFMTableNameAttribute   tableNameAttribute;
    TableName               tblName             = subStr(_backendID,1,strScan(_backendID,'/',1,strLen(_backendID)) - 1);
    container               backendIDcon        = TFMHelper::strSplit(_backendID,'/').pack();
    tableNameAttribute = new TFMTableNameAttribute(tblName,conLen(backendIDcon) == 7 ? conPeek(backendIDcon,7) : '');
    ret = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    if (classIdGet(ret) == className2Id(_baseClassName))
    {
        tableNameAttribute = new TFMTableNameAttribute(tblName);
        ret = SysExtensionAppClassFactory::getClassFromSysAttribute(_baseClassName, tableNameAttribute);
    }
    ret.clearValues();
    return ret;
}
